Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Script:Lock = Get-Content (Join-Path $PSScriptRoot 'upstream-lock.json') -Raw -Encoding UTF8 | ConvertFrom-Json
function Get-MimaTarget([string]$Location){if([string]::IsNullOrWhiteSpace($Location)){ $Location=Join-Path $env:USERPROFILE 'SillyTavern-Compat-1.19.0' };return [IO.Path]::GetFullPath($Location)}
function Assert-LoopbackConfig([string]$Location){$config=Join-Path $Location 'config.yaml';if(Test-Path $config){$raw=Get-Content $config -Raw -Encoding UTF8;if($raw -match '(?m)^\s*listen\s*:\s*true\s*(?:#.*)?$'){throw 'E_SIDE_CAR_UNSAFE_BIND: 发现 listen:true，拒绝启动；此工具只允许 loopback' };if($raw -match '(?m)^\s*listenAddressIPv4\s*:\s*(?!127\.0\.0\.1)[^#\r\n]+'){throw 'E_SIDE_CAR_UNSAFE_BIND: 存在非 loopback 监听地址' }}}
function Assert-PortAvailable([int]$Port){$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,$Port);try{$listener.Start()}catch{throw "E_SIDE_CAR_PORT_OCCUPIED: 127.0.0.1:$Port 已被占用，不得误杀其他程序"}finally{try{$listener.Stop()}catch{}}}
function Assert-Node {if(-not (Get-Command node -ErrorAction SilentlyContinue)){throw 'E_SIDE_CAR_NO_NODE: 缺少 Node.js，请先从 nodejs.org 安装受支持的 LTS 版本'};$v=& node -p 'process.versions.node';Write-Host "Node.js $v"}
function Assert-Installed([string]$Location){if(-not (Test-Path (Join-Path $Location '.mima-sidecar-install.json'))){throw '此目录未由咪嘛馆 sidecar 工具安装；禁止覆盖或结束其它 SillyTavern 进程'};if(-not (Test-Path (Join-Path $Location 'server.js'))){throw '缺少 server.js，安装不完整'}}
function Read-OwnedProcess([string]$Location){$path=Join-Path $Location '.mima-owned-process.json';if(-not(Test-Path $path)){return $null};$record=Get-Content $path -Raw -Encoding UTF8|ConvertFrom-Json;$proc=Get-CimInstance Win32_Process -Filter "ProcessId = $($record.pid)" -ErrorAction SilentlyContinue;if(-not $proc){return $null};if(-not $proc.CommandLine -or -not $proc.CommandLine.Contains([IO.Path]::GetFullPath((Join-Path $Location 'server.js')))){throw 'E_SIDE_CAR_OWNERSHIP_UNVERIFIED: 进程 PID 已被别的进程复用，不予操作'};$actual=(Get-Process -Id $record.pid).StartTime.ToUniversalTime().ToString('o');if($actual -ne $record.startedUtc){throw 'E_SIDE_CAR_OWNERSHIP_UNVERIFIED: 进程启动时间不一致，不予操作'};return $proc}
